    const storage = {
      read(key, fallback) {
        try {
          const raw = window.localStorage.getItem(key)
          return raw === null ? fallback : JSON.parse(raw)
        } catch {
          return fallback
        }
      },
      write(key, value) {
        try {
          window.localStorage.setItem(key, JSON.stringify(value))
        } catch {
          /* storage may be unavailable; state stays in memory */
        }
      },
    }

    function useStored(key, fallback) {
      const [value, setValue] = useState(() => storage.read(key, fallback))
      const update = useCallback((next) => {
        setValue((prev) => {
          const resolved = typeof next === 'function' ? next(prev) : next
          storage.write(key, resolved)
          return resolved
        })
      }, [key])
      return [value, update]
    }

    const FEATURE_DEFAULTS = {
      recent: true,
      chat: true,
      search: true,
      viewOptions: true,
      hoverCard: true,
      dragSort: true,
      composerChatSwitch: true,
      chatWorkspace: true,
    }

    let featureCache = null
    const featureListeners = new Set()

    function readFeatures() {
      if (featureCache !== null) return featureCache
      const stored = storage.read('dswb.features.v1', {})
      const merged = { ...FEATURE_DEFAULTS }
      if (stored && typeof stored === 'object') {
        for (const key of Object.keys(FEATURE_DEFAULTS)) {
          if (typeof stored[key] === 'boolean') merged[key] = stored[key]
        }
      }
      featureCache = merged
      return merged
    }

    function writeFeatures(next) {
      featureCache = { ...FEATURE_DEFAULTS, ...next }
      storage.write('dswb.features.v1', featureCache)
      for (const listener of featureListeners) listener(featureCache)
    }

    function useFeatures() {
      const [value, setValue] = useState(readFeatures)
      useEffect(() => {
        featureListeners.add(setValue)
        return () => featureListeners.delete(setValue)
      }, [])
      return value
    }

