    /** Collapsible changelog block for the bundle page. */
    function ChangelogSection(props) {
      const { t: translate } = props
      const t = typeof translate === 'function' ? translate : (key) => key
      const [open, setOpen] = useState(false)
      return h('section', { className: 'dswb-group' }, [
        h('div', { key: 'head', className: 'dswb-group-head' }, h('button', {
          key: 'toggle',
          type: 'button',
          className: 'dswb-group-title dswb-group-toggle',
          'aria-expanded': open,
          onClick: () => setOpen((prev) => !prev),
        }, [
          h('span', { key: 'c', className: 'dswb-caret' + (open ? ' open' : ''), 'aria-hidden': true }, '›'),
          h('span', { key: 'l' }, t('changelog')),
        ])),
        open ? h('ul', { key: 'list', className: 'dswb-cards' }, CHANGELOG.map((entry) => h('li', {
          key: entry.version,
          className: 'dswb-card',
        }, h('div', { className: 'dswb-card-head' }, h('div', { className: 'dswb-card-main' }, [
          h('div', { key: 'h', className: 'dswb-log-head' }, [
            h('span', { key: 'tm', className: 'dswb-log-time' }, entry.time),
            h('span', { key: 'sep', className: 'dswb-log-dash' }, '|'),
            h('span', { key: 't' }, entry.title),
          ]),
          h('ul', { key: 'u', className: 'dswb-log-items' }, entry.items.map((line, index) => h('li', { key: index }, line))),
        ]))))) : null,
      ])
    }

