    function Menu({ menu, t, onClose, onPick }) {
      const ref = useRef(null)
      const [tip, setTip] = useState(null)
      useEffect(() => {
        const onDown = (event) => {
          if (ref.current && ref.current.contains(event.target)) return
          onClose()
        }
        const onKey = (event) => {
          if (event.key === 'Escape') onClose()
        }
        document.addEventListener('pointerdown', onDown, true)
        document.addEventListener('keydown', onKey, true)
        return () => {
          document.removeEventListener('pointerdown', onDown, true)
          document.removeEventListener('keydown', onKey, true)
        }
      }, [onClose])

      const items = menu.items
      const width = 244
      const separators = items.filter((item) => item.separator).length
      const height = items.length * 32 + separators * 9 + 18
      const left = Math.max(8, Math.min(menu.x, window.innerWidth - width - 8))
      const top = Math.max(8, Math.min(menu.y, window.innerHeight - height - 8))

      const showTip = (event, text) => {
        const rect = event.currentTarget.getBoundingClientRect()
        const maxLeft = window.innerWidth - 380
        setTip({
          text,
          left: Math.max(8, Math.min(rect.right + 10, maxLeft)),
          top: rect.top + rect.height / 2,
        })
      }

      return h(React.Fragment, null, [
        h('div', {
          key: 'menu',
          ref,
          className: 'dswb-menu',
          role: 'menu',
          style: { left, top },
          onContextMenu: (event) => event.preventDefault(),
        }, items.map((item, index) => [
          item.separator ? h('div', { key: 'sep' + index, className: 'dswb-sep' }) : null,
          h('button', {
            key: item.id,
            type: 'button',
            role: 'menuitem',
            className: item.danger ? 'dswb-danger' : undefined,
            onMouseEnter: item.title ? (event) => showTip(event, item.title) : undefined,
            onMouseLeave: item.title ? () => setTip(null) : undefined,
            onClick: () => {
              onClose()
              onPick(item)
            },
          }, [
            h('span', { key: 'i', className: 'dswb-mico' }, item.icon || null),
            h('span', { key: 'l', className: 'dswb-mlabel' }, item.label),
            item.checked ? h('span', { key: 'c', className: 'dswb-check' }, '✓') : null,
            !item.checked && item.shortcut ? h('span', { key: 'k', className: 'dswb-mkey' }, item.shortcut) : null,
          ]),
        ])),
        tip ? h('div', {
          key: 'tip',
          className: 'dswb-tip',
          role: 'tooltip',
          style: { left: tip.left, top: tip.top },
        }, tip.text) : null,
      ])
    }

